function matTypeFor(key) { return MATTYPE[key] || 'concrete'; }

function scaleBoxUV(geo, w, h, d, scale = 1) {
  const uv = geo.attributes.uv;
  if (!uv) return;
  const dims = [[d, h], [d, h], [w, d], [w, d], [w, h], [w, h]];
  for (let f = 0; f < 6; f++) {
    for (let i = 0; i < 4; i++) {
      const idx = f * 4 + i;
      if (idx >= uv.count) continue;
      uv.setXY(idx, uv.getX(idx) * dims[f][0] * scale, uv.getY(idx) * dims[f][1] * scale);
    }
  }
  uv.needsUpdate = true;
}
function scalePlaneUV(geo, w, h, scale = 1) {
  const uv = geo.attributes.uv;
  if (!uv) return;
  for (let i = 0; i < uv.count; i++) uv.setXY(i, uv.getX(i) * w * scale, uv.getY(i) * h * scale);
  uv.needsUpdate = true;
