function queueGeo(geo, matKey, matrix, cast = true, receive = true) {
  const mat = M[matKey];
  if (!mat) { console.warn('Unknown material', matKey); return; }
  let g = geo.index ? geo.toNonIndexed() : geo.clone();
  g.applyMatrix4(matrix);
  for (const name of Object.keys(g.attributes)) {
    if (name !== 'position' && name !== 'normal' && name !== 'uv') g.deleteAttribute(name);
  }
  if (!g.attributes.uv) {
    const count = g.attributes.position.count;
    g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(count * 2), 2));
  }
  g.clearGroups();
  const key = mat.uuid + (cast ? 'C' : 'c') + (receive ? 'R' : 'r');
  if (!staticBatches.has(key)) staticBatches.set(key, { mat, cast, receive, geos: [] });
  staticBatches.get(key).geos.push(g);
}

