  const geo = new THREE.BoxGeometry(w, h, d);
  scaleBoxUV(geo, w, h, d, opts.uvScale ?? 1);
  _e.set(opts.rx || 0, opts.ry || 0, opts.rz || 0);
  _q.setFromEuler(_e);
