function addColliderFromBox(x, y, z, w, h, d, mat, playerBlock = true, ry = 0) {
  let hw = w / 2, hd = d / 2;
  if (ry) {
    const c = Math.abs(Math.cos(ry)), s = Math.abs(Math.sin(ry));
    const nw = hw * c + hd * s, nd = hw * s + hd * c;
    hw = nw; hd = nd;
  }
  addColliderBox(x - hw, y - h / 2, z - hd, x + hw, y + h / 2, z + hd, mat, playerBlock);
