      merged = batch.geos.length === 1 ? batch.geos[0] : mergeGeometries(batch.geos, false);
    } catch (err) {
      console.warn('Static merge failed', err);
      continue;
    }
    if (!merged) continue;
    merged.computeBoundingSphere();
    const mesh = new THREE.Mesh(merged, batch.mat);
    mesh.castShadow = batch.cast;
    mesh.receiveShadow = batch.receive;
    mesh.matrixAutoUpdate = false;
    scene.add(mesh);
    drawCalls++;
    verts += merged.attributes.position.count;
    for (const g of batch.geos) g.dispose();
