M.weed = std({ color: 0x525b37, roughness: .95 });

// ---------------------------------------------------------------------------
// Facade helpers
// ---------------------------------------------------------------------------
function windowPanel(cx, cy, cz, w, h, face, state = 'dark', frameMat = 'metalDark') {
  // face: +x, -x, +z, -z
  const alongX = face === '+z' || face === '-z';
  const t = .035;
  let gx = cx, gz = cz, gw = w, gd = t;
  if (alongX) { gd = w; gw = t; }
  let glassMat = state === 'lit' ? 'glassLit' : state === 'broken' ? 'glassBroken' : 'glassDark';
  addBox(gx, cy, gz, gw, h, gd, glassMat, { cast: false });
  // frame
  const fw = .055;
  if (alongX) {
    addBox(cx, cy - h / 2 - fw / 2, cz, w + .16, fw, .09, frameMat, { cast: false });
    addBox(cx, cy + h / 2 + fw / 2, cz, w + .16, fw, .09, frameMat, { cast: false });
    addBox(cx - w / 2 - fw / 2, cy, cz, fw, h + .16, .09, frameMat, { cast: false });
    addBox(cx + w / 2 + fw / 2, cy, cz, fw, h + .16, .09, frameMat, { cast: false });
    addBox(cx, cy, cz, .035, h, .075, frameMat, { cast: false });
    addBox(cx, cy - h / 2 + .16, cz + .02, w + .12, .07, .16, 'concreteDark', { cast: false });
  } else {
    addBox(cx, cy - h / 2 - fw / 2, cz, .09, fw, w + .16, frameMat, { cast: false });
    addBox(cx, cy + h / 2 + fw / 2, cz, .09, fw, w + .16, frameMat, { cast: false });
    addBox(cx, cy, cz - w / 2 - fw / 2, .09, h + .16, fw, frameMat, { cast: false });
    addBox(cx, cy, cz + w / 2 + fw / 2, .09, h + .16, fw, frameMat, { cast: false });
    addBox(cx, cy, cz, .075, h, .035, frameMat, { cast: false });
    addBox(cx + .02, cy - h / 2 + .16, cz, .16, .07, w + .12, 'concreteDark', { cast: false });
  }
  if (state === 'broken') {
    // jagged remnants
    for (let i = 0; i < 5; i++) {
      const a = mr(0, TAU), r = mr(.1, .45);
      const sx = cx + Math.cos(a) * w * .38, sz = cz + Math.sin(a) * w * .38;
      const geo = new THREE.CircleGeometry(mr(.03, .1), 3);
      _e.set(mr(0, TAU), mr(0, TAU), mr(0, TAU)); _q.setFromEuler(_e);
      _m4.compose(new THREE.Vector3(sx, cy + mr(-h * .4, h * .4), sz), _q, _one);
      queueGeo(geo, 'shard', _m4, false, false);
    }
  }
  if (state === 'boarded') {
    addBox(cx, cy, cz, alongX ? w * 1.1 : .07, .12, alongX ? .07 : w * 1.1, 'wood', { rz: .12, cast: false });
    addBox(cx, cy + .2, cz, alongX ? w * 1.02 : .07, .1, alongX ? .07 : w * 1.02, 'woodDark', { rz: -.16, cast: false });
  }
  if (state === 'lit' && mapRand() < .4) {
    // curtain silhouette
    addBox(cx, cy + .2, cz + (face === '+z' ? -.02 : .02), alongX ? w * .4 : .02, h * .3, alongX ? .02 : w * .4, 'glassLit', { cast: false });
  }
}

function acUnit(x, y, z, face) {
  const alongX = face === '+z' || face === '-z';
  addBox(x, y, z, alongX ? .7 : .38, .42, alongX ? .38 : .7, 'metal', { collide: false });
  addBox(x, y + .02, z, alongX ? .56 : .42, .3, alongX ? .42 : .56, 'metalDark', { cast: false });
  if (alongX) addCylinder(x, y + .02, z + (face === '+z' ? .2 : -.2), .13, .13, .025, 12, 'metalDark', { rx: Math.PI / 2, cast: false });
  else addCylinder(x + (face === '+x' ? .2 : -.2), y + .02, z, .13, .13, .025, 12, 'metalDark', { rz: Math.PI / 2, cast: false });
  addBox(x, y - .25, z, alongX ? .78 : .08, .05, alongX ? .08 : .78, 'metalDark', { cast: false });
}

function facadeWindows(x0, z0, x1, z1, side, floors, groundH, floorH, opts = {}) {
  // side is which wall faces the street: +x,-x,+z,-z
  const isX = side === '+x' || side === '-x';
  const length = isX ? (z1 - z0) : (x1 - x0);
  const cols = opts.cols || Math.max(2, Math.floor(length / 3.2));
  const margin = opts.margin ?? 1.8;
  const usable = length - margin * 2;
  const spacing = usable / Math.max(1, cols - 1);
  for (let f = 1; f < floors; f++) {
    const cy = groundH + (f - 1) * floorH + floorH * .56;
    for (let c = 0; c < cols; c++) {
      const along = (isX ? z0 : x0) + margin + c * spacing;
      const x = isX ? (side === '+x' ? x1 + .03 : x0 - .03) : along;
      const z = isX ? along : (side === '+z' ? z1 + .03 : z0 - .03);
      let state = mapRand() < .12 ? 'lit' : mapRand() < .09 ? 'broken' : mapRand() < .04 ? 'boarded' : 'dark';
      windowPanel(x, cy, z, opts.windowW || 1.25, opts.windowH || 1.45, side, state, opts.frameMat || 'metalDark');
      if (mapRand() < .16) acUnit(x + (side === '+x' ? .28 : side === '-x' ? -.28 : 0), cy - 1.05, z + (side === '+z' ? .28 : side === '-z' ? -.28 : 0), side);
      if (opts.sills !== false && mapRand() < .7) {
        if (isX) addBox(x + (side === '+x' ? .08 : -.08), cy - .8, z, .18, .09, 1.55, 'concreteDark', { cast: false });
        else addBox(x, cy - .8, z + (side === '+z' ? .08 : -.08), 1.55, .09, .18, 'concreteDark', { cast: false });
      }
    }
  }
}

function storefront(x, y, z, w, h, face, mat = 'glass', frame = 'metalDark', awningColor = 'paintRed') {
  const alongX = face === '+z' || face === '-z';
  addBox(x, y + h / 2, z, alongX ? w : .04, h, alongX ? .04 : w, mat, { cast: false });
  // lower kick panel
  addBox(x, y + .32, z, alongX ? w : .08, .64, alongX ? .08 : w, 'woodDark', { cast: false });
  // frame
  const t = .1;
  addBox(x, y + h + .05, z, alongX ? w + .2 : .16, .1, alongX ? .16 : w + .2, frame, { cast: false });
  for (let i = -1; i <= 1; i++) {
    const off = i * w / 2;
    addBox(x + (alongX ? off : 0), y + h / 2, z + (alongX ? 0 : off), alongX ? .07 : .16, h, alongX ? .16 : .07, frame, { cast: false });
  }
  // awning
  if (awningColor) {
    addBox(x, y + h + .18, z + (face === '+z' ? .35 : face === '-z' ? -.35 : 0), alongX ? w + .5 : .8, .12, alongX ? .8 : w + .5, awningColor, { rz: 0, cast: true });
    if (alongX) addBox(x, y + h + .06, z + (face === '+z' ? .7 : -.7), w + .5, .08, .1, frame, { cast: false });
  }
}

function addSign(x, y, z, w, h, matKey, ry = 0, rx = 0) {
  addPlane(x, y, z, w, h, matKey, { ry, rx, cast: false, receive: false });
}
</script>

