+    addBox(cx, cy + h / 2 + fw / 2, cz, .09, fw, w + .16, frameMat, { cast: false });
+    addBox(cx, cy, cz - w / 2 - fw / 2, .09, h + .16, fw, frameMat, { cast: false });
+    addBox(cx, cy, cz + w / 2 + fw / 2, .09, h + .16, fw, frameMat, { cast: false });
+    addBox(cx, cy, cz, .075, h, .035, frameMat, { cast: false });
