const sw = MAP.sidewalk, road = MAP.road;
// sidewalk strips around the two avenues
const strips = [
  [-63, -road / 2 - sw, -road / 2, road / 2 + sw],
  [road / 2, -road / 2 - sw, 63, road / 2 + sw],
  [-63, -road / 2 - sw, -road / 2, road / 2 + sw],
  [-63, road / 2, 63, road / 2 + sw],
  [-road / 2 - sw, -63, road / 2 + sw, -road / 2],
  [-road / 2 - sw, road / 2, road / 2 + sw, 63]
];
// four long strips parallel to Z
for (const s of [
  [-63, -road / 2 - sw, -road / 2, road / 2 + sw],
  [road / 2, -road / 2 - sw, 63, road / 2 + sw],
  [-63, road / 2, 63, road / 2 + sw],
  [-63, -road / 2 - sw, 63, -road / 2]
]) {
  const [x0, z0, x1, z1] = s;
  addBox((x0 + x1) / 2, .08, (z0 + z1) / 2, x1 - x0, .16, z1 - z0, 'sidewalk', { uvScale: .16, collide: true, playerBlock: false, cast: false });
  addHeightRect(x0, z0, x1, z1, .16);
}
// four cross strips
for (const s of [
  [-63, -road / 2 - sw, -road / 2, road / 2 + sw],
  [road / 2, -road / 2 - sw, 63, road / 2 + sw],
  [-63, -road / 2 - sw, -road / 2, road / 2 + sw],
  [-63, road / 2, 63, road / 2 + sw]
]) {
  const [x0, z0, x1, z1] = s;
  addBox((x0 + x1) / 2, .08, (z0 + z1) / 2, x1 - x0, .16, z1 - z0, 'sidewalk', { uvScale: .16, collide: true, playerBlock: false, cast: false });
  addHeightRect(x0, z0, x1, z1, .16);
}
// corner sidewalk pads
for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
  const x0 = sx < 0 ? -road / 2 - sw : road / 2;
  const x1 = sx < 0 ? -road / 2 : road / 2 + sw;
  const z0 = sz < 0 ? -road / 2 - sw : road / 2;
  const z1 = sz < 0 ? -road / 2 : road / 2 + sw;
  addBox((x0 + x1) / 2, .08, (z0 + z1) / 2, x1 - x0, .16, z1 - z0, 'sidewalk', { uvScale: .16, collide: true, playerBlock: false, cast: false });
  addHeightRect(x0, z0, x1, z1, .16);
}

