const sw = MAP.sidewalk, road = MAP.road;
const inner = road / 2, outer = road / 2 + sw;
// sidewalks along the north-south avenue, split at the crossing
for (const sx of [-1, 1]) {
  for (const zr of [[-63, -outer], [outer, 63]]) {
