    const x1 = sx < 0 ? -inner : outer;
    addBox((x0 + x1) / 2, .08, (zr[0] + zr[1]) / 2, x1 - x0, .16, zr[1] - zr[0], 'sidewalk', { uvScale: .16, collide: true, playerBlock: false, cast: false });
    addHeightRect(x0, zr[0], x1, zr[1], .16);
  }
}
// sidewalks along the east-west avenue
for (const sz of [-1, 1]) {
  for (const xr of [[-63, -outer], [outer, 63]]) {
    const z0 = sz < 0 ? -outer : inner;
    const z1 = sz < 0 ? -inner : outer;
    addBox((xr[0] + xr[1]) / 2, .08, (z0 + z1) / 2, xr[1] - xr[0], .16, z1 - z0, 'sidewalk', { uvScale: .16, collide: true, playerBlock: false, cast: false });
    addHeightRect(xr[0], z0, xr[1], z1, .16);
  }
}
// corner pads at the four crossing corners
for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
  const x0 = sx < 0 ? -outer : inner;
  const x1 = sx < 0 ? -inner : outer;
  const z0 = sz < 0 ? -outer : inner;
  const z1 = sz < 0 ? -inner : outer;
  addBox((x0 + x1) / 2, .08, (z0 + z1) / 2, x1 - x0, .16, z1 - z0, 'sidewalk', { uvScale: .16, collide: true, playerBlock: false, cast: false });
  addHeightRect(x0, z0, x1, z1, .16);
}

