function wallOpeningX(z, x0, x1, y0, y1, t, mat, openings, collide = true) {
  const list = [...openings].sort((a, b) => a.a - b.a);
  let cursor = x0;
  const solid = (a, b) => {
    if (b - a < .01) return;
    addBox((a + b) / 2, (y0 + y1) / 2, z, b - a, y1 - y0, t, mat, { collide, playerBlock: true, uvScale: 1 });
  };
  for (const o of list) {
    solid(cursor, o.a);
    if (o.bottom > y0) addBox((o.a + o.b) / 2, (y0 + o.bottom) / 2, z, o.b - o.a, o.bottom - y0, t, mat, { collide, playerBlock: true });
    if (o.top < y1) addBox((o.a + o.b) / 2, (o.top + y1) / 2, z, o.b - o.a, y1 - o.top, t, mat, { collide, playerBlock: true });
    if (o.glass) {
      addBox((o.a + o.b) / 2, (o.bottom + o.top) / 2, z, o.b - o.a, o.top - o.bottom, .025, 'glass', { cast: false });
      addColliderBox(o.a, o.bottom, z - .09, o.b, o.top, z + .09, 'glass', true);
