      addBox((o.a + o.b) / 2, o.top + .035, z, o.b - o.a + .14, .07, .09, 'metalDark', { cast: false });
      addBox((o.a + o.b) / 2, o.bottom - .035, z, o.b - o.a + .14, .07, .09, 'metalDark', { cast: false });
