M.cardboard = std({ color: 0x8d7350, roughness: .96, metalness: 0, map: TEX.paper });

// --- background blocks -----------------------------------------------------
function buildBackdrop() {
  const blocks = [
    [-50, 54, 24, 10, 13, 'brickDark'], [24, 54, 26, 10, 17, 'plasterDark'],
    [-54, -56, 26, 12, 15, 'plasterDark'], [26, -56, 28, 12, 12, 'brickDark'],
    [-59, 22, 10, 28, 18, 'plasterDark'], [-59, -22, 10, 28, 12, 'brickDark'],
    [59, 22, 10, 28, 14, 'brickDark'], [59, -22, 10, 28, 20, 'plasterDark']
  ];
  for (const [cx, cz, w, d, h, mat] of blocks) {
    addBox(cx, h / 2, cz, w, h, d, mat, { uvScale: .16, collide: true });
    addBox(cx, h + .25, cz, w + .4, .5, d + .4, 'concreteDark', { cast: false });
    const cols = Math.max(2, Math.floor(w / 4)), rows = Math.max(2, Math.floor(h / 3.5));
    for (let f = 1; f < rows; f++) for (let c = 0; c < cols; c++) {
      const x = cx - w / 2 + 2 + c * ((w - 4) / Math.max(1, cols - 1));
      const y = 2.0 + f * 3.2;
      const z = cz + (cz > 0 ? -d / 2 - .03 : d / 2 + .03);
      windowPanel(x, y, z, 1.15, 1.4, cz > 0 ? '-z' : '+z', mapRand() < .08 ? 'lit' : mapRand() < .12 ? 'broken' : 'dark', 'metalDark');
    }
  }
  // distant skyline silhouettes, low draw cost
  for (let i = 0; i < 28; i++) {
    const a = (i / 28) * TAU + mr(-.05, .05);
    const r = mr(100, 160);
    const h = mr(18, 55);
    addBox(Math.cos(a) * r, h / 2 - 2, Math.sin(a) * r, mr(12, 24), h, mr(12, 24), 'concreteDark', { cast: false, receive: false, uvScale: .1 });
  }
  // boundary colliders
  addColliderBox(-66, 0, -66, -62, 12, 66, 'concrete', true);
  addColliderBox(62, 0, -66, 66, 12, 66, 'concrete', true);
  addColliderBox(-66, 0, -66, 66, 12, -62, 'concrete', true);
  addColliderBox(-66, 0, 62, 66, 12, 66, 'concrete', true);
}

// --- props -----------------------------------------------------------------
function addSandbagWall(cx, cz, rot, length = 4.0, rows = 3) {
  const count = Math.max(3, Math.round(length / .62));
  const dirx = Math.cos(rot), dirz = -Math.sin(rot);
  for (let r = 0; r < rows; r++) {
    const n = count - (r % 2 ? 1 : 0);
    for (let i = 0; i < n; i++) {
      const off = (i - (n - 1) / 2) * .58;
      const x = cx + dirx * off + mr(-.035, .035);
      const z = cz + dirz * off + mr(-.035, .035);
      addSphere(x, .17 + r * .25, z, .31, .18, .23, 'burlap', { ry: rot + mr(-.18, .18), seg: 7, seg2: 5, cast: true });
    }
  }
  addColliderFromBox(cx, rows * .125, cz, length, rows * .25, .55, 'dirt', true, rot);
}
function addJerseyBarrier(cx, cz, rot, length = 2.6, warn = true) {
  const shape = new THREE.Shape();
  shape.moveTo(-.42, 0); shape.lineTo(-.33, .18); shape.lineTo(-.18, .72); shape.lineTo(-.12, 1.0);
  shape.lineTo(.12, 1.0); shape.lineTo(.18, .72); shape.lineTo(.33, .18); shape.lineTo(.42, 0);
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, { depth: length, bevelEnabled: true, bevelSize: .025, bevelThickness: .025, bevelSegments: 2, steps: 1 });
  geo.translate(0, 0, -length / 2);
  _e.set(0, rot, 0); _q.setFromEuler(_e);
  _m4.compose(new THREE.Vector3(cx, .16, cz), _q, _one);
  queueGeo(geo, 'concrete', _m4, true, true);
  if (warn) {
    addBox(cx, .84, cz, .7, .23, .05, 'hazard', { ry: rot, cast: false });
  }
  addColliderFromBox(cx, .6, cz, .85, 1.0, length, 'concrete', true, rot);
}
function addDumpster(cx, cz, rot = 0, color = 'greenMetal') {
  addBox(cx, .75, cz, 2.3, 1.3, 1.4, color, { ry: rot, collide: true, uvScale: 1.5 });
  addBox(cx, 1.46, cz, 2.4, .12, 1.5, color, { ry: rot, rx: .06, cast: true });
  addBox(cx - .7, 1.6, cz, .6, .06, 1.4, 'metalDark', { ry: rot, cast: false });
  for (const sx of [-1, 1]) addCylinder(cx + Math.cos(rot) * sx * .82, .2, cz - Math.sin(rot) * sx * .82, .2, .2, .12, 10, 'rubber', { rz: Math.PI / 2, ry: rot, cast: false });
  addBox(cx, 1.08, cz, 2.34, .06, 1.44, 'metalDark', { ry: rot, cast: false });
  addBox(cx, .85, cz, 2.3, .08, 1.42, 'rust', { ry: rot, cast: false });
  addColliderFromBox(cx, .75, cz, 2.3, 1.5, 1.4, 'metal', true, rot);
}
function addCrate(cx, cz, s = .8, rot = 0, stack = 0) {
  addBox(cx, s / 2 + .18 + stack * s, cz, s, s, s, 'wood', { ry: rot, uvScale: 1.4, collide: true });
  addBox(cx, .18 + stack * s + s + .01, cz, s * .96, .04, s * .96, 'woodDark', { ry: rot, cast: false });
  addBox(cx, .18 + stack * s + s * .5, cz, s + .015, .07, s + .015, 'woodDark', { ry: rot, cast: false });
}
function addBarrel(cx, cz, mat = 'rust') {
  addCylinder(cx, .68, cz, .39, .39, 1.2, 12, mat, { collide: true });
  addCylinder(cx, 1.0, cz, .4, .4, .04, 12, 'metalDark', { cast: false });
  addCylinder(cx, .32, cz, .4, .4, .04, 12, 'metalDark', { cast: false });
}
function addTrafficLight(cx, cz, rot = 0) {
  addCylinder(cx, 2.9, cz, .12, .15, 5.8, 10, 'metalDark', { collide: true });
  addBox(cx + Math.cos(rot) * 2.8, 5.55, cz - Math.sin(rot) * 2.8, 5.6, .13, .13, 'metalDark', { ry: rot, cast: true });
  const hx = cx + Math.cos(rot) * 5.2, hz = cz - Math.sin(rot) * 5.2;
  addBox(hx, 5.05, hz, .55, 1.55, .5, 'metalDark', { ry: rot, cast: true });
  addSphere(hx + Math.cos(rot) * .3, 5.48, hz - Math.sin(rot) * .3, .15, .15, .06, 'signalRed', { ry: rot, cast: false });
  addSphere(hx + Math.cos(rot) * .3, 5.08, hz - Math.sin(rot) * .3, .15, .15, .06, 'signalYellow', { ry: rot, cast: false });
  addSphere(hx + Math.cos(rot) * .3, 4.68, hz - Math.sin(rot) * .3, .15, .15, .06, 'signalGreen', { ry: rot, cast: false });
}
M.signalRed = std({ color: 0x4c1612, emissive: 0xff2b18, emissiveIntensity: 2.5, roughness: .25 });
M.signalYellow = std({ color: 0x4d3c10, emissive: 0xffb31c, emissiveIntensity: .15, roughness: .25 });
M.signalGreen = std({ color: 0x0e2e1d, emissive: 0x32e376, emissiveIntensity: .15, roughness: .25 });

function addStreetLamp(cx, cz, rot = 0) {
  addCylinder(cx, 3.8, cz, .1, .16, 7.6, 10, 'metalDark', { collide: true });
  addBox(cx + Math.cos(rot) * 1.0, 7.5, cz - Math.sin(rot) * 1.0, 2.1, .1, .1, 'metalDark', { ry: rot, cast: true });
  addBox(cx + Math.cos(rot) * 1.95, 7.36, cz - Math.sin(rot) * 1.95, .75, .18, .36, 'metalDark', { ry: rot, cast: true });
  addBox(cx + Math.cos(rot) * 1.95, 7.25, cz - Math.sin(rot) * 1.95, .55, .04, .25, 'bulbDim', { ry: rot, cast: false });
}
M.bulbDim = std({ color: 0x9f9a86, roughness: .4, metalness: .2 });
function addHydrant(x, z) {
  addCylinder(x, .42, z, .16, .19, .65, 10, 'paintRed', { collide: true });
  addSphere(x, .78, z, .2, .14, .2, 'paintRed', { cast: true });
  addCylinder(x, .46, z, .28, .28, .09, 10, 'paintRed', { rz: Math.PI / 2, cast: false });
}
function addCone(x, z, rot = 0) {
  addCylinder(x, .08, z, .19, .2, .05, 10, 'paint', { cast: false });
  addCylinder(x, .33, z, .035, .15, .48, 10, 'paintYellow', { cast: false });
  addCylinder(x, .28, z, .12, .14, .07, 10, 'paint', { cast: false });
}
function addPallet(cx, cz, rot = 0) {
  addBox(cx, .1, cz, 1.3, .12, 1.1, 'woodDark', { ry: rot, collide: false });
  for (let i = 0; i < 4; i++) addBox(cx + Math.cos(rot) * (-.45 + i * .3), .18, cz - Math.sin(rot) * (-.45 + i * .3), .22, .06, 1.1, 'wood', { ry: rot, cast: false });
}
function addTrashPile(cx, cz) {
  for (let i = 0; i < 6; i++) addSphere(cx + mr(-.8, .8), .22 + mr(0, .2), cz + mr(-.7, .7), mr(.16, .3), mr(.14, .26), mr(.16, .3), 'trashBag', { seg: 7, seg2: 5, ry: mr(0, TAU), cast: true });
  for (let i = 0; i < 5; i++) addPlane(cx + mr(-1.2, 1.2), .018 + groundHeightAt(cx, cz), cz + mr(-1.2, 1.2), mr(.2, .5), mr(.2, .55), 'paper', { rx: -Math.PI / 2, rz: mr(0, TAU) });
}
M.trashBag = std({ color: 0x222420, roughness: .72, metalness: .02 });
</script>

