envCanvas.width = 1024; envCanvas.height = 512;
{
  const ec = envCanvas.getContext('2d');
  const g = ec.createLinearGradient(0, 0, 0, 512);
  g.addColorStop(0, '#526a74'); g.addColorStop(.42, '#879596'); g.addColorStop(.5, '#c3bda9');
  g.addColorStop(.56, '#6d6c63'); g.addColorStop(1, '#232522');
  ec.fillStyle = g; ec.fillRect(0, 0, 1024, 512);
  const sg = ec.createRadialGradient(210, 172, 4, 210, 172, 90);
  sg.addColorStop(0, 'rgba(255,242,210,1)'); sg.addColorStop(.2, 'rgba(255,214,154,.8)'); sg.addColorStop(1, 'rgba(255,190,120,0)');
  ec.fillStyle = sg; ec.fillRect(100, 60, 240, 240);
  ec.fillStyle = 'rgba(60,65,64,.32)';
  for (let i = 0; i < 26; i++) {
    ec.beginPath(); ec.ellipse(Math.random() * 1024, 110 + Math.random() * 120, 60 + Math.random() * 130, 8 + Math.random() * 18, 0, 0, TAU); ec.fill();
  }
}
const envTex = new THREE.CanvasTexture(envCanvas);
envTex.mapping = THREE.EquirectangularReflectionMapping;
envTex.colorSpace = THREE.SRGBColorSpace;
const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromEquirectangular(envTex).texture;
scene.environmentIntensity = 0.58;
pmrem.dispose();
envTex.dispose();

const camera = new THREE.PerspectiveCamera(76, innerWidth / innerHeight, 0.012, 320);

