// ============================================================================
// WEAPON — AKM pattern rifle, fully procedural
// ============================================================================
function wMesh(geo, mat, parent, x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0, sx = 1, sy = 1, sz = 1) {
  const m = new THREE.Mesh(geo, mat);
  m.position.set(x, y, z);
  m.rotation.set(rx, ry, rz);
  m.scale.set(sx, sy, sz);
  m.castShadow = false; m.receiveShadow = false;
  parent.add(m);
  return m;
}
function wBox(w, h, d, mat, parent, x, y, z, rx = 0, ry = 0, rz = 0, r = 0) {
  const geo = r ? new RoundedBoxGeometry(w, h, d, 2, r) : new THREE.BoxGeometry(w, h, d);
  return wMesh(geo, mat, parent, x, y, z, rx, ry, rz);
}
function wCyl(r1, r2, h, seg, mat, parent, x, y, z, rx = 0, ry = 0, rz = 0) {
  return wMesh(new THREE.CylinderGeometry(r1, r2, h, seg), mat, parent, x, y, z, rx, ry, rz);
}
function wSphere(r, mat, parent, x, y, z, sx = 1, sy = 1, sz = 1) {
  return wMesh(new THREE.SphereGeometry(r, 12, 8), mat, parent, x, y, z, 0, 0, 0, sx, sy, sz);
}
function extrudeYZ(points, width, mat, parent, x = 0, y = 0, z = 0, bevel = .003) {
  const shape = new THREE.Shape();
  shape.moveTo(points[0][0], points[0][1]);
  for (let i = 1; i < points.length; i++) shape.lineTo(points[i][0], points[i][1]);
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, { depth: width, bevelEnabled: bevel > 0, bevelSize: bevel, bevelThickness: bevel, bevelSegments: 2, steps: 1 });
  geo.rotateY(-Math.PI / 2);
  geo.translate(width / 2, 0, 0);
  return wMesh(geo, mat, parent, x, y, z);
}

