      const d = buf.getChannelData(c);
      for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 3.1);
    }
    conv.buffer = buf;
    const wet = this.ctx.createGain(); wet.gain.value = .16;
    conv.connect(wet); wet.connect(this.master);
    this.wet = conv;
    const nlen = Math.floor(this.ctx.sampleRate * 1.2);
    this.noise = this.ctx.createBuffer(1, nlen, this.ctx.sampleRate);
