  },
  gunshot() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const out = this.ctx.createGain(); out.gain.value = .85; out.connect(this.master); out.connect(this.wet);
    // crack
    const n1 = this.src(out); const hp = this.ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 1700;
    const g1 = this.ctx.createGain(); g1.gain.setValueAtTime(.8, t); g1.gain.exponentialRampToValueAtTime(.001, t + .09);
    n1.connect(hp); hp.connect(g1); n1.start(t); n1.stop(t + .1);
    // body
    const n2 = this.src(out); const lp = this.ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.setValueAtTime(1700, t); lp.frequency.exponentialRampToValueAtTime(240, t + .2);
