    this.baseSize = new Float32Array(capacity);
    this.geo = new THREE.BufferGeometry();
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.p, 3));
    this.geo.setAttribute('aColor', new THREE.BufferAttribute(this.c, 3));
    this.geo.setAttribute('aSize', new THREE.BufferAttribute(this.s, 1));
    this.geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.a, 1));
    this.mat = new THREE.ShaderMaterial({
      uniforms: { map: { value: texture } },
      transparent: true, depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
      vertexShader: `attribute vec3 aColor; attribute float aSize; attribute float aAlpha; varying vec3 vColor; varying float vAlpha;
        void main(){ vColor=aColor; vAlpha=aAlpha; vec4 mv=modelViewMatrix*vec4(position,1.0); gl_PointSize=aSize*(260.0/max(0.1,-mv.z)); gl_Position=projectionMatrix*mv; }`,
      fragmentShader: `uniform sampler2D map; varying vec3 vColor; varying float vAlpha;
        void main(){ vec4 t=texture2D(map,gl_PointCoord); if(t.a<.01) discard; gl_FragColor=vec4(vColor,t.a*vAlpha); }`
    });
    this.points = new THREE.Points(this.geo, this.mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);
  }
  spawn(x, y, z, vx, vy, vz, life, size, color, grav = 0, drag = .5, grow = 0) {
    const i = this.count < this.capacity ? this.count++ : Math.floor(Math.random() * this.capacity);
    const i3 = i * 3;
    this.p[i3] = x; this.p[i3 + 1] = y; this.p[i3 + 2] = z;
    this.vel[i3] = vx; this.vel[i3 + 1] = vy; this.vel[i3 + 2] = vz;
    this.c[i3] = color.r; this.c[i3 + 1] = color.g; this.c[i3 + 2] = color.b;
    this.s[i] = size; this.a[i] = 1; this.life[i] = life; this.maxLife[i] = life;
    this.grav[i] = grav; this.drag[i] = drag; this.grow[i] = grow; this.baseSize[i] = size;
    this.geo.attributes.aColor.needsUpdate = true;
  }
  update(dt) {
    for (let i = 0; i < this.count; i++) {
      if (this.life[i] <= 0) { this.a[i] = 0; continue; }
      this.life[i] -= dt;
      const i3 = i * 3;
      this.vel[i3 + 1] -= this.grav[i] * dt;
      const dr = Math.exp(-this.drag[i] * dt);
      this.vel[i3] *= dr; this.vel[i3 + 1] *= dr; this.vel[i3 + 2] *= dr;
      this.p[i3] += this.vel[i3] * dt; this.p[i3 + 1] += this.vel[i3 + 1] * dt; this.p[i3 + 2] += this.vel[i3 + 2] * dt;
      const t = 1 - this.life[i] / this.maxLife[i];
      this.a[i] = Math.max(0, (1 - t) * (1 - t * .3));
      this.s[i] = this.baseSize[i] * (1 + this.grow[i] * t);
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.aSize.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;
  }
}
