// PROJECTILES / BALLISTICS
// ============================================================================
const BULLET_MAX = 18;
const bullets = [];
const tracerMat = new THREE.LineBasicMaterial({ color: 0xffd49a, transparent: true, opacity: .9, blending: THREE.AdditiveBlending, depthWrite: false });
const tracerPool = [];
for (let i = 0; i < BULLET_MAX; i++) {
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
  const line = new THREE.Line(geo, tracerMat.clone());
  line.frustumCulled = false;
  line.visible = false;
  scene.add(line);
  tracerPool.push(line);
}
const _rayHit = { t: 0, normal: new THREE.Vector3(), mat: 'concrete' };
function rayBox(ox, oy, oz, dx, dy, dz, box, out) {
  let tmin = 0, tmax = Infinity, axis = -1, sign = 1;
  const o = [ox, oy, oz], d = [dx, dy, dz];
  const min = [box.min.x, box.min.y, box.min.z], max = [box.max.x, box.max.y, box.max.z];
  for (let i = 0; i < 3; i++) {
    if (Math.abs(d[i]) < 1e-9) {
      if (o[i] < min[i] || o[i] > max[i]) return false;
    } else {
      let t1 = (min[i] - o[i]) / d[i], t2 = (max[i] - o[i]) / d[i];
      let s = -1;
      if (t1 > t2) { const tt = t1; t1 = t2; t2 = tt; s = 1; }
      if (t1 > tmin) { tmin = t1; axis = i; sign = s; }
      tmax = Math.min(tmax, t2);
      if (tmin > tmax) return false;
    }
  }
  if (axis < 0) return false;
  out.t = tmin;
  out.normal.set(0, 0, 0);
  out.normal.setComponent(axis, sign);
  out.mat = box.mat;
  return true;
}
function traceSegment(a, b, out) {
  const dx = b.x - a.x, dy = b.y - a.y, dz = b.z - a.z;
  const len = Math.hypot(dx, dy, dz);
  if (len < 1e-6) return false;
  const nx = dx / len, ny = dy / len, nz = dz / len;
  let best = len, bestBox = null, bestNormal = null;
  for (const c of colliders) {
    if (!rayBox(a.x, a.y, a.z, nx, ny, nz, c, _rayHit)) continue;
    if (_rayHit.t < best && _rayHit.t >= 0) {
      best = _rayHit.t; bestBox = c; bestNormal = _rayHit.normal.clone(); out.mat = _rayHit.mat;
    }
  }
  if (bestBox) {
    out.t = best; out.normal.copy(bestNormal); out.point = a.clone().addScaledVector(new THREE.Vector3(nx, ny, nz), best); return true;
  }
  return false;
}
const _traceHit = { t: 0, normal: new THREE.Vector3(), mat: 'concrete', point: new THREE.Vector3() };
function spawnBullet(dir, muzzlePos) {
  const start = new THREE.Vector3().copy(camera.position).addScaledVector(dir, .45);
  const vel = dir.clone().multiplyScalar(245);
  const tracer = tracerPool[bullets.length % tracerPool.length];
  tracer.visible = true;
  tracer.material.opacity = .9;
  const geo = tracer.geometry;
  geo.attributes.position.setXYZ(0, muzzlePos.x, muzzlePos.y, muzzlePos.z);
  geo.attributes.position.setXYZ(1, muzzlePos.x, muzzlePos.y, muzzlePos.z);
  geo.attributes.position.needsUpdate = true;
  bullets.push({ pos: start, vel, prev: start.clone(), life: 0, tracer, muzzle: muzzlePos.clone(), dead: false });
}
function removeBullet(b, i) {
  b.tracer.visible = false;
  bullets.splice(i, 1);
}
function updateBullets(dt) {
  for (let i = bullets.length - 1; i >= 0; i--) {
    const b = bullets[i];
    b.life += dt;
    const speed = b.vel.length();
    const steps = Math.max(1, Math.min(4, Math.ceil(speed * dt / 1.1)));
    const sdt = dt / steps;
    let hit = false;
    for (let s = 0; s < steps; s++) {
      const prev = b.pos.clone();
      b.vel.y -= 9.81 * sdt;
      const next = b.pos.clone().addScaledVector(b.vel, sdt);
      if (traceSegment(prev, next, _traceHit)) {
        impactAt(_traceHit.point, _traceHit.normal, _traceHit.mat);
        hit = true;
        break;
      }
      b.pos.copy(next);
    }
    if (hit || b.life > 3.2) { removeBullet(b, i); continue; }
    const geo = b.tracer.geometry;
    geo.attributes.position.setXYZ(0, b.muzzle.x, b.muzzle.y, b.muzzle.z);
    geo.attributes.position.setXYZ(1, b.pos.x, b.pos.y, b.pos.z);
    geo.attributes.position.needsUpdate = true;
    b.tracer.material.opacity = Math.max(0, .9 - b.life * 1.5);
  }
}
const impactLight = new THREE.PointLight(0xffc27a, 0, 3.2, 2);
scene.add(impactLight);
let impactLightT = 0;
function impactAt(point, normal, mat) {
  const dustN = mat === 'metal' ? 5 : mat === 'glass' ? 8 : 11;
  const col = mat === 'metal' ? new THREE.Color(0x77736a) : mat === 'wood' ? new THREE.Color(0x8b6a49) : mat === 'glass' ? new THREE.Color(0x9eb6b2) : mat === 'brick' ? new THREE.Color(0x9e7664) : new THREE.Color(0xaea593);
  for (let i = 0; i < dustN; i++) {
    const dir = normal.clone().add(new THREE.Vector3(rnd(-.6, .6), rnd(-.2, .8), rnd(-.6, .6))).normalize();
    dustParticles.spawn(point.x + dir.x * .03, point.y + dir.y * .03, point.z + dir.z * .03,
      dir.x * rnd(.5, 2.8) + rnd(-.5, .5), dir.y * rnd(.4, 2.2) + .4, dir.z * rnd(.5, 2.8) + rnd(-.5, .5),
      rnd(.45, 1.15), rnd(.07, .18), col, mat === 'metal' ? .2 : 1.0, mat === 'metal' ? 2.4 : 2.0, 2.5);
