  if (mat === 'metal' || mat === 'glass') {
    for (let i = 0; i < (mat === 'glass' ? 16 : 9); i++) {
      const dir = normal.clone().add(new THREE.Vector3(rnd(-1, 1), rnd(-.5, 1.2), rnd(-1, 1))).normalize();
