    }
  }
  addImpactDecal(point, normal, mat, mat === 'metal' ? .8 : 1);
  impactLight.position.copy(point).addScaledVector(normal, .15);
  impactLightT = .09;
  if (mat === 'metal') Audio.ping(rnd(.04, .09), rnd(1600, 3300));
  else if (mat === 'glass') Audio.ping(rnd(.05, .1), rnd(2800, 5200));
  else Audio.thud(rnd(.06, .12), mat === 'wood' ? 150 : 110);
}

