function tryShoot() {
  if (!game.started || game.paused) return;
  if (W.reloading || W.inspect || game.drawT < .7) return;
  if (W.ammo <= 0) {
    if (!W.emptyClicked) { Audio.click(.5, 2400, .035, 2.5); W.emptyClicked = true; }
    if (!W.reloading) startReload();
    return;
  }
  if (W.fireCooldown > 0) return;
  W.fireCooldown = W.fireInterval;
  W.ammo--;
  W.shots++;
  W.lastShotAt = game.time;
  W.emptyClicked = false;
  W.boltCycle = 1;
  W.trigger = 1;
  W.flashT = .055;
  W.flashSeed = Math.random() * 100;
  W.smokeTimer = 0;
  if (W.ammo === 0) W.boltLocked = true;
  Audio.gunshot();
  // aim direction with spread
  const moveSpread = Math.min(1, player.speed / 6.5);
  const base = W.adsT > .72 ? .0011 : .0068;
  const spread = base + moveSpread * (W.adsT > .72 ? .0028 : .017) + (player.grounded ? 0 : .015) + (W.sprinting ? .024 : 0);
  const dir = new THREE.Vector3();
  camera.getWorldDirection(dir);
  const right = new THREE.Vector3(1, 0, 0).applyQuaternion(camera.quaternion);
  const up = new THREE.Vector3(0, 1, 0).applyQuaternion(camera.quaternion);
  const a = Math.random() * TAU, r = Math.sqrt(Math.random()) * spread;
  dir.addScaledVector(right, Math.cos(a) * r).addScaledVector(up, Math.sin(a) * r).normalize();
  const muzzlePos = new THREE.Vector3();
  muzzleGroup.getWorldPosition(muzzlePos);
  spawnBullet(dir, muzzlePos);
  // recoil
  const adsFactor = lerp(1, .58, W.adsT);
  const kick = rnd(.0072, .0115) * adsFactor;
  player.pitch = clamp(player.pitch + kick * .46, -1.48, 1.48);
  player.yaw += rnd(-.0042, .0042) * adsFactor;
  camRecoil.pitch += kick * .9;
  camRecoil.yaw += rnd(-.004, .004) * adsFactor;
  camRecoil.roll += rnd(-.0035, .0035);
  W.recoilZ += rnd(.028, .046) * adsFactor;
  W.recoilY += rnd(.008, .015) * adsFactor;
  W.recoilRX += rnd(.03, .05) * adsFactor;
  W.recoilRY += rnd(-.014, .014) * adsFactor;
  W.recoilRZ += rnd(-.012, .012) * adsFactor;
  // casing
  const ej = new THREE.Vector3();
  ejectionAnchor.getWorldPosition(ej);
  const camRight = new THREE.Vector3(1, 0, 0).applyQuaternion(camera.quaternion);
  const camUp = new THREE.Vector3(0, 1, 0).applyQuaternion(camera.quaternion);
  const camBack = new THREE.Vector3(0, 0, 1).applyQuaternion(camera.quaternion);
  const vel = camRight.multiplyScalar(rnd(1.8, 3.1)).addScaledVector(camUp, rnd(1.2, 2.3)).addScaledVector(camBack, rnd(.3, 1.1)).add(player.vel.clone().multiplyScalar(.3));
  spawnCasing(ej, vel);
  // muzzle smoke
  const mdir = new THREE.Vector3(0, 0, -1).applyQuaternion(gun.getWorldQuaternion(new THREE.Quaternion()));
  for (let i = 0; i < 2; i++) {
    dustParticles.spawn(muzzlePos.x, muzzlePos.y, muzzlePos.z, mdir.x * rnd(.5, 1.8) + rnd(-.25, .25), mdir.y * rnd(.5, 1.8) + rnd(.1, .4), mdir.z * rnd(.5, 1.8) + rnd(-.25, .25), rnd(.5, 1.0), rnd(.05, .12), smokeColor, -.1, 1.4, 3.2);
  }
  updateHudAmmo();
}
function startReload() {
  if (W.reloading || game.drawT < .7 || W.reserve <= 0 || W.ammo >= W.magSize) return;
  W.reloading = true; W.reloadT = 0; W.reloadStage = 0;
  W.reloadEmpty = W.ammo === 0;
  W.reloadDur = W.reloadEmpty ? 2.85 : 2.2;
  W.aiming = false;
  W.inspect = false;
  $('reload-ring').style.opacity = 1;
}
function finishReload() {
  const need = W.magSize - W.ammo;
  const take = Math.min(need, W.reserve);
  W.ammo += take; W.reserve -= take;
  W.reloading = false; W.boltLocked = false;
  $('reload-ring').style.opacity = 0;
  updateHudAmmo();
}
function startInspect() {
  if (W.reloading || game.drawT < .7 || W.inspect) return;
  W.inspect = true; W.inspectT = 0; W.aiming = false;
}
function cancelInspect() {
  W.inspect = false; W.inspectT = 0;
}

