// ============================================================================
// PLAYER MOVEMENT
// ============================================================================
function collidesAt(x, z, feet, height) {
  const r = player.radius;
  for (const c of colliders) {
    if (!c.playerBlock) continue;
    if (feet + height <= c.min.y + .03 || feet >= c.max.y - .03) continue;
    const cx = clamp(x, c.min.x, c.max.x);
    const cz = clamp(z, c.min.z, c.max.z);
    const dx = x - cx, dz = z - cz;
    if (dx * dx + dz * dz < r * r) return true;
  }
  return false;
}
function updatePlayer(dt) {
  const crouching = !!keys.KeyC && player.grounded;
  const wantSprint = !!keys.ShiftLeft && !!keys.KeyW && !crouching && player.stamina > 1 && !W.aiming && !W.reloading;
  W.sprinting = wantSprint && player.grounded && !W.inspect;
  if (W.sprinting) player.stamina = Math.max(0, player.stamina - 22 * dt);
  else player.stamina = Math.min(100, player.stamina + (player.crouchT > .4 ? 18 : 12) * dt);
  if (player.stamina <= 0) W.sprinting = false;
  player.crouchT = damp(player.crouchT, crouching ? 1 : 0, 11, dt);
  const currentHeight = lerp(player.height, player.crouchH, player.crouchT);
  player.eye = lerp(1.64, 1.06, player.crouchT);

  const fwd = new THREE.Vector3(-Math.sin(player.yaw), 0, -Math.cos(player.yaw));
  const right = new THREE.Vector3(Math.cos(player.yaw), 0, -Math.sin(player.yaw));
  const wish = new THREE.Vector3();
  if (keys.KeyW) wish.add(fwd);
  if (keys.KeyS) wish.sub(fwd);
  if (keys.KeyD) wish.add(right);
  if (keys.KeyA) wish.sub(right);
  if (wish.lengthSq() > 0) wish.normalize();
  let speed = W.aiming ? 2.35 : crouching ? 2.15 : 4.3;
  if (W.sprinting) speed = 6.9;
  if (!player.grounded) speed *= .88;
  const target = wish.multiplyScalar(speed);
  const accel = player.grounded ? (wish.lengthSq() > 0 ? 32 : 22) : 7.5;
  player.vel.x += clamp(target.x - player.vel.x, -accel * dt, accel * dt);
  player.vel.z += clamp(target.z - player.vel.z, -accel * dt, accel * dt);
  // jump
  if (keys.Space && player.grounded && game.started && !game.paused) {
    player.vel.y = 5.15; player.grounded = false; keys.Space = false;
    Audio.footstep(true);
  }
  player.vel.y -= 15.8 * dt;
  // horizontal movement with collision
  const dx = player.vel.x * dt, dz = player.vel.z * dt;
  const feet = player.pos.y;
  if (!collidesAt(player.pos.x + dx, player.pos.z, feet + .05, currentHeight - .05)) player.pos.x += dx;
  else player.vel.x *= .1;
  if (!collidesAt(player.pos.x, player.pos.z + dz, feet + .05, currentHeight - .05)) player.pos.z += dz;
  else player.vel.z *= .1;
  // vertical
  player.pos.y += player.vel.y * dt;
  const gh = groundHeightAt(player.pos.x, player.pos.z);
  if (player.pos.y <= gh + .001) {
    if (!player.grounded && player.vel.y < -3.5) {
      player.landing = Math.min(.1, Math.abs(player.vel.y) * .012);
      Audio.footstep(true);
      dustParticles.spawn(player.pos.x, gh + .05, player.pos.z, 0, .3, 0, .5, .22, dustColor, .2, 1.5, 2);
    }
    player.pos.y = gh; player.vel.y = 0; player.grounded = true;
  } else player.grounded = false;
  // step up onto sidewalks
  if (player.grounded && Math.abs(player.pos.y - gh) < .3) player.pos.y = gh;
  player.speed = Math.hypot(player.vel.x, player.vel.z);
  // head bob + footsteps
  if (player.grounded && player.speed > .3) {
    player.bobPhase += dt * (W.sprinting ? 12.5 : 9.2) * clamp(player.speed / 4.3, .5, 1.4);
    player.stepDist += player.speed * dt;
    const stepLen = W.sprinting ? 2.1 : 2.5;
    if (player.stepDist > stepLen) { player.stepDist = 0; Audio.footstep(W.sprinting); }
  }
  player.bob = damp(player.bob, player.grounded ? Math.min(1, player.speed / 5) : 0, 8, dt);
  player.landing = damp(player.landing, 0, 8, dt);
  if (!game.started) { player.yaw = -.04; player.pitch = -.015; }
  // camera
  const bobY = Math.sin(player.bobPhase * 2) * .012 * player.bob * (1 - W.adsT * .7);
  const bobX = Math.cos(player.bobPhase) * .018 * player.bob * (1 - W.adsT * .8);
  const breathing = Math.sin(game.time * 1.55) * .0015 * (1 - player.bob * .4);
  camera.position.set(player.pos.x + bobX * .5, player.pos.y + player.eye + bobY + breathing - player.landing, player.pos.z);
  _camEuler.set(player.pitch + camRecoil.pitch, player.yaw + camRecoil.yaw, camRecoil.roll + Math.sin(player.bobPhase) * .006 * player.bob);
  camera.quaternion.setFromEuler(_camEuler);
  camRecoil.pitch = damp(camRecoil.pitch, 0, 12, dt);
  camRecoil.yaw = damp(camRecoil.yaw, 0, 12, dt);
  camRecoil.roll = damp(camRecoil.roll, 0, 10, dt);
  // fov
  const targetFov = W.adsT > .01 ? lerp(76, 52, smooth(W.adsT)) : (W.sprinting ? 80 : 76);
  camera.fov = damp(camera.fov, targetFov, 12, dt);
  camera.updateProjectionMatrix();
}

