// WEAPON ANIMATION
// ============================================================================
const _hip = new THREE.Vector3(.245, -.24, -.545);
const _ads = new THREE.Vector3(0, -.085, -.43);
const _sprintPos = new THREE.Vector3(.32, -.31, -.48);
const _sprintRot = new THREE.Vector3(-.24, .5, .25);
const _tmpVec = new THREE.Vector3();
let reloadSoundStage = 0;
function updateWeapon(dt) {
  W.fireCooldown = Math.max(0, W.fireCooldown - dt);
  W.adsT = damp(W.adsT, (W.aiming && !W.reloading && !W.sprinting && !W.inspect) ? 1 : 0, 12, dt);
  W.sprintT = damp(W.sprintT, W.sprinting ? 1 : 0, 8, dt);
  W.trigger = damp(W.trigger, W.triggerTarget, 28, dt);
